.card {
  border-radius: 12px;
  box-shadow: 0 1px 2px rgb(0 0 0 / 8%), 0 8px 24px rgb(0 0 0 / 12%);
  background-image: linear-gradient(180deg, #fff, #f3f4f6);
}

/* Frosted glass: expensive over large areas */
.overlay { backdrop-filter: blur(8px); }

/* A cheap shadow animation: opacity on a pseudo-element */
.btn::after { content: ""; position: absolute; inset: 0;
  box-shadow: 0 8px 24px rgb(0 0 0 / 20%); opacity: 0; transition: opacity 150ms; }
.btn:hover::after { opacity: 1; }
