```css
/* A sticky header: without top nothing sticks */
.header { position: sticky; top: 0; z-index: 10; }

/* A modal above everything */
.modal { position: fixed; inset: 0; z-index: 1000; }

/* The trap: a parent with a transform creates a stacking context,
   and a z-index of 9999 inside cannot rise above an outside element */
.animated-parent { transform: translateZ(0); }
.animated-parent .tooltip { z-index: 9999; }

/* An explicit context — when you want one deliberately */
.card { isolation: isolate; }
