@Component({ changeDetection: ChangeDetectionStrategy.OnPush })
export class Ticker implements OnInit, OnDestroy {
  private readonly cdr = inject(ChangeDetectorRef);
  value = 0;

  ngOnInit() {
    this.cdr.detach(); // removed from the general traversal
    const loop = () => {
      this.value = read();
      this.cdr.detectChanges(); // we refresh it ourselves, once per frame
      this.frame = requestAnimationFrame(loop);
    };
    loop();
  }

  ngOnDestroy() { cancelAnimationFrame(this.frame); }
}

// Data arrived from a third-party callback
thirdParty.on("data", (d) => {
  this.data = d;
  this.cdr.markForCheck(); // otherwise the screen will not update
});
