export class RatingComponent implements ControlValueAccessor {
  value = 0;
  disabled = false;
  private onChange: (v: number) => void = () => {};
  private onTouched: () => void = () => {};

  writeValue(v: number) { this.value = v ?? 0; }
  registerOnChange(fn: (v: number) => void) { this.onChange = fn; }
  registerOnTouched(fn: () => void) { this.onTouched = fn; }
  setDisabledState(isDisabled: boolean) { this.disabled = isDisabled; } // the forgotten one

  pick(star: number) {
    this.value = star;
    this.onChange(star);
    this.onTouched(); // without this the error message never appears
  }
}
